#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <limits.h>

#define MAX_LABEL 256
#define STATIC_MAGIC_0 0x4d
#define STATIC_MAGIC_1 0x56
#define STATIC_MAGIC_2 0x4d
#define STATIC_MAGIC_3 0x01

enum arg_type { ARG_NONE, ARG_IMM, ARG_LABEL };

struct opdef {
    const char *name;
    int opcode;
    int len;
    enum arg_type type;
};

static const struct opdef ops[] = {
    {"PUSH",  0xa1, 5, ARG_IMM},
    {"ADD",   0x13, 1, ARG_NONE},
    {"SUB",   0x27, 1, ARG_NONE},
    {"MUL",   0x3c, 1, ARG_NONE},
    {"DIV",   0x4e, 1, ARG_NONE},
    {"MOD",   0x5f, 1, ARG_NONE},
    {"EQ",    0x1a, 1, ARG_NONE},
    {"LT",    0x2b, 1, ARG_NONE},
    {"GT",    0x3d, 1, ARG_NONE},
    {"POP",   0xb2, 1, ARG_NONE},
    {"DUP",   0x83, 1, ARG_NONE},
    {"SWAP",  0x94, 1, ARG_NONE},
    {"PRINT", 0x61, 1, ARG_NONE},
    {"PRCH",  0x72, 1, ARG_NONE},
    {"JMP",   0xe5, 5, ARG_LABEL},
    {"JZ",    0xca, 5, ARG_LABEL},
    {"JNZ",   0xdb, 5, ARG_LABEL},
    {"HALT",  0x00, 1, ARG_NONE},
    {NULL, 0, 0, ARG_NONE}
};

struct label {
    char name[MAX_LABEL];
    int32_t pos;
};

struct instr {
    int opcode;
    int len;
    int32_t operand;
    char label[MAX_LABEL];
    int has_label;
};

static struct label *labels = NULL;
static size_t nlabels = 0, label_cap = 0;

static struct instr *program = NULL;
static size_t ninstr = 0, instr_cap = 0;

static void fail(const char *msg)
{
    fprintf(stderr, "assembler error: %s\n", msg);
    exit(1);
}

static void *xmalloc(size_t n)
{
    void *p = malloc(n);
    if (!p) fail("out of memory");
    return p;
}

static void *xrealloc(void *p, size_t n)
{
    void *q = realloc(p, n);
    if (!q) fail("out of memory");
    return q;
}

static void add_label(const char *name, int32_t pos)
{
    size_t i;
    for (i = 0; i < nlabels; i++) {
        if (strcmp(labels[i].name, name) == 0)
            fail("duplicate label");
    }
    if (nlabels == label_cap) {
        label_cap = label_cap ? label_cap * 2 : 16;
        labels = xrealloc(labels, label_cap * sizeof(*labels));
    }
    snprintf(labels[nlabels].name, sizeof(labels[nlabels].name), "%s", name);
    labels[nlabels].pos = pos;
    nlabels++;
}

static int32_t find_label(const char *name)
{
    size_t i;
    for (i = 0; i < nlabels; i++) {
        if (strcmp(labels[i].name, name) == 0)
            return labels[i].pos;
    }
    fail("undefined label");
    return 0;
}

static void add_instruction(int opcode, int len, int has_label)
{
    if (ninstr == instr_cap) {
        instr_cap = instr_cap ? instr_cap * 2 : 16;
        program = xrealloc(program, instr_cap * sizeof(*program));
    }
    memset(&program[ninstr], 0, sizeof(program[ninstr]));
    program[ninstr].opcode = opcode;
    program[ninstr].len = len;
    program[ninstr].has_label = has_label;
    ninstr++;
}

static char *trim(char *s)
{
    char *end;
    while (*s && isspace((unsigned char)*s)) s++;
    end = s + strlen(s);
    while (end > s && isspace((unsigned char)end[-1])) *--end = '\0';
    return s;
}

static const struct opdef *lookup_op(const char *name)
{
    int i;
    for (i = 0; ops[i].name; i++) {
        if (strcmp(ops[i].name, name) == 0)
            return &ops[i];
    }
    return NULL;
}

static void parse_i32(const char *s, int32_t *out)
{
    char *end = NULL;
    long v;
    errno = 0;
    v = strtol(s, &end, 10);
    if (errno || end == s || *end != '\0') fail("invalid integer");
    if (v < INT32_MIN || v > INT32_MAX) fail("integer out of signed 32-bit range");
    *out = (int32_t)v;
}

static void copy_label(char *dst, size_t dstsz, const char *src)
{
    size_t n = strlen(src);
    if (n == 0 || n >= dstsz) fail("invalid label name");
    memcpy(dst, src, n + 1);
}

int main(int argc, char **argv)
{
    FILE *fp;
    char *line = NULL;
    size_t linecap = 0;
    ssize_t nread;
    int32_t pos = 0;
    size_t i;
    static const unsigned char key[4] = {0x2e, 0x9c, 0x3f, 0x7a};
    uint64_t out_index = 0;

    if (argc != 2) {
        fprintf(stderr, "usage: %s <assembly.s>\n", argv[0]);
        return 1;
    }

    fp = fopen(argv[1], "rb");
    if (!fp) {
        fprintf(stderr, "assembler error: cannot open %s\n", argv[1]);
        return 1;
    }

    while ((nread = getline(&line, &linecap, fp)) != -1) {
        char *s, *p, *arg;
        const struct opdef *op;

        (void)nread;

        s = strchr(line, ';');
        if (s) *s = '\0';
        s = trim(line);
        if (*s == '\0') continue;

        p = strchr(s, ':');
        if (p) {
            char *name_end = p;
            char *after = p + 1;
            char name[MAX_LABEL];
            size_t nlen;

            while (name_end > s && isspace((unsigned char)name_end[-1]))
                name_end--;
            while (*after && isspace((unsigned char)*after))
                after++;
            if (*after != '\0')
                fail("invalid label line");
            if (name_end == s)
                fail("empty label name");

            nlen = (size_t)(name_end - s);
            if (nlen >= sizeof(name)) fail("label name too long");
            for (i = 0; i < nlen; i++) {
                if (isspace((unsigned char)s[i]))
                    fail("invalid label name");
                name[i] = s[i];
            }
            name[nlen] = '\0';
            add_label(name, pos);
            continue;
        }

        p = s;
        while (*p && !isspace((unsigned char)*p)) p++;
        if (*p) {
            *p++ = '\0';
            arg = trim(p);
            if (*arg == '\0') arg = NULL;
        } else {
            arg = NULL;
        }

        op = lookup_op(s);
        if (!op) fail("unknown mnemonic");

        if (op->type == ARG_NONE) {
            if (arg != NULL) fail("unexpected operand");
            add_instruction(op->opcode, op->len, 0);
        } else if (op->type == ARG_IMM) {
            int32_t v;
            if (arg == NULL) fail("missing integer operand");
            parse_i32(arg, &v);
            add_instruction(op->opcode, op->len, 0);
            program[ninstr - 1].operand = v;
        } else {
            if (arg == NULL) fail("missing label operand");
            add_instruction(op->opcode, op->len, 1);
            copy_label(program[ninstr - 1].label, sizeof(program[ninstr - 1].label), arg);
        }

        pos += op->len;
    }

    fclose(fp);
    free(line);

    for (i = 0; i < ninstr; i++) {
        if (program[i].has_label)
            program[i].operand = find_label(program[i].label);
    }

    {
        unsigned char header[4] = {STATIC_MAGIC_0, STATIC_MAGIC_1, STATIC_MAGIC_2, STATIC_MAGIC_3};
        if (fwrite(header, 1, sizeof(header), stdout) != sizeof(header))
            fail("failed writing output");
    }

    for (i = 0; i < ninstr; i++) {
        unsigned char raw[5];
        int j;
        int len = program[i].len;

        raw[0] = (unsigned char)program[i].opcode;
        if (len == 5) {
            uint32_t v = (uint32_t)program[i].operand;
            raw[1] = (unsigned char)(v & 0xff);
            raw[2] = (unsigned char)((v >> 8) & 0xff);
            raw[3] = (unsigned char)((v >> 16) & 0xff);
            raw[4] = (unsigned char)((v >> 24) & 0xff);
        }

        for (j = 0; j < len; j++) {
            unsigned char b = raw[j] ^ key[out_index & 3];
            if (fputc(b, stdout) == EOF)
                fail("failed writing output");
            out_index++;
        }
    }

    free(program);
    free(labels);
    return 0;
}
